#!/usr/bin/env python3
# Apache-2.0. Original content output is CC-BY-4.0; no active writes.
import hashlib
import json
from pathlib import Path

ROOT = Path.cwd()
OWN = Path('curricula/DE/Gymnasium/quality/goal-evidence/2026-10-13/chemie-e594-residual-source-duty-author-20261013-v3')
assert not (ROOT / OWN / 'FINAL.finite-residual-source-duty-author.freeze.json').exists(), 'Immutable sealed author root; use a new root for a successor.'
CAS = OWN / 'candidate/two-full-classification-goals-and-dye-parent-whole-CAS.author.json'
whole = json.loads((ROOT / CAS).read_text())['newWholeGoals']

def digest(value):
    return 'sha256:' + hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(',', ':')).encode()).hexdigest()

def binding(path):
    data = (ROOT / path).read_bytes()
    return {'path': str(path), 'sha256': 'sha256:' + hashlib.sha256(data).hexdigest(), 'bytes': len(data)}

def write(name, obj):
    path = ROOT / OWN / name
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(obj, ensure_ascii=False, indent=2) + '\n')

def case(index, suffix, titles, data, clauses, answers, expectations):
    goal = whole[index]
    case_id = goal['id'][:8] + '-classification-transfer-' + suffix
    task = ['\n'.join(f'{i + 1}. {row[language]}' for i, row in enumerate(clauses)) for language in range(2)]
    rubric = []
    for i, (clause, answer, expectation_ids) in enumerate(zip(clauses, answers, expectations)):
        row = {'criterionId': case_id + '-r' + str(i + 1), 'expectationIds': expectation_ids,
               'taskClauseDe': clause[0], 'taskClauseEn': clause[1],
               'criterionDe': answer[0], 'criterionEn': answer[1], 'maximumPoints': 2,
               'partialCreditDe': '2 Punkte für die vollständige fachlich begründete Antwort auf diesen ausdrücklich geforderten Teil; 1 Punkt für eine fachlich richtige, aber unvollständige Zuordnung oder Begründung; 0 Punkte für fehlende oder fachlich falsche Belege.',
               'partialCreditEn': '2 points for the complete scientifically justified response to this explicitly requested part; 1 point for a correct but incomplete assignment or justification; 0 points for missing or scientifically incorrect evidence.',
               'creditBasis': 'written-explicit-task'}
        for language, field in enumerate(['De', 'En']):
            start = task[language].index(clause[language])
            row['taskSpan' + field] = {'start': start, 'end': start + len(clause[language])}
        rubric.append(row)
    return {'caseId': case_id, 'goalId': goal['id'], 'titleDe': titles[0], 'titleEn': titles[1],
            'wholeGoalCASBinding': binding(CAS), 'wholeGoalPointer': '/newWholeGoals/' + str(index),
            'wholeGoalStableJsonSha256': digest(goal),
            'dataOrigin': 'Original invented paper cards and material records, not measured samples, actual experiments or regulatory claims. Structural motifs are schematic; no copied primary-source definition or image.',
            'languageParity': 'Complete DE/EN data, task, model answer, rubric and exact demand spans',
            'dataDe': data[0], 'dataEn': data[1], 'taskDe': task[0], 'taskEn': task[1],
            'modelAnswerDe': '\n'.join(f'{i + 1}. {r[0]}' for i, r in enumerate(answers)),
            'modelAnswerEn': '\n'.join(f'{i + 1}. {r[1]}' for i, r in enumerate(answers)),
            'expectationIds': list(dict.fromkeys(e for group in expectations for e in group)),
            'rubric': rubric, 'maximumPoints': 2 * len(rubric),
            'visualizationRequired': False, 'practicalExecutionRequired': False,
            'executionClaim': 'No learner performance, synthesis, laboratory execution or mastery occurred.',
            'gradingBoundary': 'Credit is limited to the explicit classification demands. Mechanisms, spectra, naming alone or a memorized family list do not replace the requested classification and reasoning. One sufficiently rich independent transfer may establish the whole goal; the paired cases are alternatives, not a quota.',
            'sourceCourseAcceptance': 'AUTHOR design only. Actual selected WP/W/WB entitlement, independent review and compiled-page binding remain unresolved.'}

cases = []
cases.append(case(0, '1', ('Eine Farbmittelsammlung nach fünf Kriterien ordnen', 'Organize a colourant collection by five criteria'), (
    'Vier fiktive Materialakten für eine Papieraufgabe; Ar bezeichnet einen aromatischen Rest, Ph einen Phenylrest und Me eine Methylgruppe. A: Na⁺[⁻O₃S–C₆H₄–N=N–C₆H₄–OH]; im angegebenen Wasserbad löslich, synthetisch, direkt aus dem Bad auf die Faser aufgebracht, zur Textilfärbung. B: ein Ar–N=N–Ar′-Farbmittel mit voluminösen aromatischen Resten; im angegebenen Wasserbad unlöslich, synthetisch, als Partikel mit Bindemittel aufgetragen, Beschichtungsfarbe. C: [(p-Me₂N–C₆H₄)₂C(Ph)]⁺; drei Arylreste am zentralen C ohne C–H-Bindung, Gegenion nicht gezeigt; im angegebenen Wasserbad löslich, synthetisch, direkt aus einer Lösung eingesetzt, Indikatorfarbmittel. D: ein glycosyliertes Flavylium-System: positiv geladenes O im konjugierten sechsgliedrigen O-Heteroring, ein Phenylrest an Position 2 und ein O-gebundener Zucker; im angegebenen Wasserbad löslich, aus Pflanzen gewonnen, direkt aus einer Lösung eingesetzt, Lebensmittelfarbmittel. Die Akten liefern Herkunft, Verwendung und Färbeverfahren; aus den Strukturfragmenten allein sollen diese Angaben nicht erraten werden. Pigment/Farbstoff bezeichnet hier die Unlöslichkeit/Löslichkeit im ausdrücklich genannten Anwendungsmedium. Sicherheits- oder Zulassungsentscheidungen werden nicht geprüft.',
    'Four invented material records for a paper task; Ar denotes an aromatic residue, Ph a phenyl residue and Me a methyl group. A: Na⁺[⁻O₃S–C₆H₄–N=N–C₆H₄–OH]; soluble in the specified aqueous bath, synthetic, applied directly from the bath to a fibre, textile colourant. B: an Ar–N=N–Ar′ colourant with bulky aromatic residues; insoluble in the specified aqueous bath, synthetic, applied as particles with a binder, coating colourant. C: [(p-Me₂N–C₆H₄)₂C(Ph)]⁺; three aryl residues on central C with no C–H bond, counterion not shown; soluble in the specified aqueous bath, synthetic, used directly from a solution, indicator colourant. D: a glycosylated flavylium system: positively charged O in a conjugated six-membered O heterocycle, a phenyl residue at position 2 and an O-linked sugar; soluble in the specified aqueous bath, obtained from plants, used directly from a solution, food colourant. The records supply origin, use and colouring process; these must not be guessed from structural fragments alone. Here pigment/dye denotes insolubility/solubility in the explicitly specified application medium. Safety or approval decisions are not assessed.'), [
    ('Stelle die vertretenen Strukturklassen kurz vor und ordne A–D mit einer jeweils charakteristischen Strukturbegründung zu. Berücksichtige Azofarbstoffe und mindestens zwei weitere Klassen.', 'Briefly introduce the represented structural classes and assign A–D with a characteristic structural justification for each. Include azo dyes and at least two further classes.'),
    ('Ordne alle vier Akten zusätzlich nach Löslichkeit im angegebenen Medium, Herkunft, Färbemethode und Verwendung. Benenne für jede Spalte das Einteilungskriterium und trenne gelieferte Aktenangaben von strukturell begründeten Aussagen.', 'Also classify all four records by solubility in the stated medium, origin, colouring method and use. Name the criterion for each column and distinguish supplied record information from structurally justified statements.'),
    ('Erkläre anhand von A/B und C/D, warum zwei Farbmittel nach einem Kriterium zusammen und nach einem anderen getrennt werden können. Widerlege die Aussage: „Aus derselben Strukturklasse folgen dieselbe Löslichkeit, Herkunft und Verwendung.“', 'Using A/B and C/D, explain why two colourants can be grouped by one criterion and separated by another. Refute the statement: “The same structural class implies the same solubility, origin and use.”')], [
    ('A und B sind Azo-Farbmittel, begründet durch die Aryl–N=N–Aryl-Verknüpfung. C ist ein Triphenylmethanfarbstoff: drei Arylreste sind an das kationische, konjugationsfähige zentrale C gebunden; die Dimethylaminogruppen sind Donoren. D ist ein Anthocyan, erkennbar am glycosylierten Flavylium-System. Damit werden Azo-, Triphenylmethan- und Anthocyan-Klasse vorgestellt und angewandt; kein Synthesemechanismus ist dafür erforderlich.', 'A and B are azo colourants, justified by the aryl–N=N–aryl linkage. C is a triphenylmethane dye: three aryl residues are attached to the cationic central C capable of conjugation; dimethylamino groups are donors. D is an anthocyanin, recognized by its glycosylated flavylium system. This introduces and applies azo, triphenylmethane and anthocyanin classes; no synthesis mechanism is required.'),
    ('Löslichkeit: A/C/D sind in diesem Wasserbad lösliche Farbstoffe, B ein unlösliches Pigment. Herkunft: A/B/C synthetisch, D pflanzlich-natürlich. Färbemethode: A direkte Badfärbung, B Partikelauftrag mit Bindemittel, C/D direkter Einsatz aus Lösung; diese Angaben rechtfertigen keine erfundene Küpenroute. Verwendung: A Textil, B Beschichtung, C Indikator, D Lebensmittel. Strukturklasse ist durch Bau begründet; die anderen vier Spalten stützen sich auf die ausdrücklich gelieferten Akten bzw. Mediumsangaben.', 'Solubility: A/C/D are soluble dyes in this aqueous bath; B is an insoluble pigment. Origin: A/B/C synthetic, D plant-derived natural. Colouring method: A direct bath dyeing, B particulate binder application, C/D direct use from solution; these records do not justify an invented vat route. Use: A textile, B coating, C indicator, D food. Structural class is justified by constitution; the other four columns use the explicitly supplied record or medium information.'),
    ('A/B gehören beide zur Azo-Strukturklasse, unterscheiden sich aber im genannten Medium als Farbstoff/Pigment und in Verfahren/Verwendung. C/D sind beide wasserlösliche Farbmittel und direkt aus Lösung eingesetzt, gehören aber zu verschiedenen Strukturklassen und unterscheiden sich in Herkunft und Verwendung. Die Kriterien erfassen verschiedene Eigenschaften bzw. Kontexte; natürliche Herkunft, Anwendung und Löslichkeit sind keine zwingende Folge allein der Klassenbezeichnung.', 'A/B share the azo structural class but differ as dye/pigment in the stated medium and in process/use. C/D are both water-soluble colourants used directly from solution but belong to different structural classes and differ in origin and use. The criteria capture different properties or contexts; natural origin, use and solubility do not follow necessarily from the class name alone.')], [['e1'], ['e2'], ['e3']]))

cases.append(case(0, '2', ('Falsch beschriftete Farbkarten korrigieren', 'Correct incorrectly labelled colour cards'), (
    'Papierakten mit neuer Stoffvariation; Ar ist ein aromatischer Rest. X besitzt Ar–N=N–Ar′ und ionische Sulfonatgruppen; im genannten Wasserbad löslich, synthetisch hergestellt, direkte Färbung aus dem Bad, Lebensmittel-Farbmittel in der fiktiven Akte. Y besitzt eine lange zusammenhängende Kette alternierender C=C/C–C-Bindungen zwischen endständigen Kohlenstoffringen und keine Azo- oder Carbonylgruppe; im genannten Wasserbad unlöslich, im genannten Ölmedium löslich, aus Pflanzen gewonnen, direkter Einsatz im Ölmedium, fiktiver Lebensmittel-Farbmittel-Einsatz. Z besitzt ein konjugiertes Anthrachinon-Gerüst mit zwei C=O-Gruppen; im genannten Wasserbad unlöslich, synthetisch hergestellt, laut Akte nach Reduktion als lösliche Leukostufe in die Faser gebracht und dort zum unlöslichen Farbmittel oxidiert, Textilfarbe. Die anfänglichen Schilder lauten X „natürlich, weil Lebensmittel“, Y „Azo, weil ebenfalls farbig“, Z „Direktfarbstoff, weil am Ende Farbe auf der Faser ist“. Keine praktische Färbung oder Produktsicherheit wird behauptet oder bewertet.',
    'Paper records with new material variation; Ar is an aromatic residue. X has Ar–N=N–Ar′ and ionic sulfonate groups; soluble in the stated aqueous bath, synthesized, direct dyeing from the bath, food colourant use in the invented record. Y has a long continuous chain of alternating C=C/C–C bonds between terminal carbon rings and no azo or carbonyl group; insoluble in the stated aqueous bath, soluble in the stated oil medium, obtained from plants, direct use in the oil medium, invented food-colourant use. Z has a conjugated anthraquinone framework with two C=O groups; insoluble in the stated aqueous bath, synthesized, according to its record reduced into a soluble leuco form introduced into a fibre and oxidized there to the insoluble colourant, textile colourant. Initial labels say X “natural because food”, Y “azo because also coloured”, Z “direct dye because colour ends up on the fibre”. No actual dyeing or product safety is claimed or assessed.'), [
    ('Stelle die drei Strukturklassen vor und ordne X/Y/Z anhand der gegebenen Strukturelemente ein. Begründe bei jedem Vertreter das Klassenmerkmal; die Einteilung muss Azo und mindestens zwei weitere Klassen enthalten.', 'Introduce the three structural classes and classify X/Y/Z using the given structural features. Justify each class feature; the classification must include azo and at least two further classes.'),
    ('Erstelle für X/Y/Z eine begründete Übersicht der Kriterien Löslichkeit, Herkunft, Färbemethode und Verwendung. Nenne bei Y das Medium und erläutere bei Z die in der Akte beschriebene Färbemethode, ohne einen Synthesemechanismus zu ergänzen.', 'Make a justified summary for X/Y/Z using the criteria solubility, origin, colouring method and use. Specify the medium for Y and explain the colouring method recorded for Z without adding a synthesis mechanism.'),
    ('Korrigiere die drei Anfangsschilder. Zeige anhand von X/Y eine gemeinsame und eine trennende Einteilung und erkläre, welche Information durch „farbig“ allein nicht gegeben ist.', 'Correct the three initial labels. Using X/Y, show one grouping and one separating classification and explain which information “coloured” alone does not provide.')], [
    ('X ist Azo, weil zwei aromatische Reste durch N=N verknüpft sind. Y ist Polyen, weil das zusammenhängende alternierende Mehrfachbindungssystem die gegebene Struktur prägt. Z ist ein Carbonylfarbstoff der Anthrachinon-Familie: C=O-Gruppen sind Teil des konjugierten Chinon-Gerüsts. Das sind drei verschiedene Strukturklassen mit Azo und zwei weiteren Klassen.', 'X is azo because two aromatic residues are linked by N=N. Y is polyene because its continuous alternating multiple-bond system characterizes the given structure. Z is a carbonyl dye of the anthraquinone family: C=O groups form part of the conjugated quinone framework. These are three distinct structural classes including azo and two further classes.'),
    ('Im Wasserbad ist X löslich, Y/Z unlöslich; Y ist im genannten Öl löslich, weshalb Löslichkeit stets das Medium braucht. X/Z sind synthetisch, Y pflanzlich-natürlich. X nutzt direkte Badfärbung, Y direkten Einsatz im Öl; Z nutzt laut Akte eine Küpenfärbung über eine lösliche reduzierte Leukostufe mit anschließender Oxidation zum unlöslichen Farbmittel. X/Y werden als Lebensmittel-Farbmittel, Z als Textilfarbe geführt. Diese Aktenangaben sind keine aus der Formel abgeleiteten Herkunfts- oder Zulassungsnachweise.', 'In the aqueous bath X is soluble and Y/Z are insoluble; Y is soluble in the stated oil, so solubility always needs a medium. X/Z are synthetic, Y plant-derived natural. X uses direct bath dyeing, Y direct use in oil; Z uses recorded vat dyeing through a soluble reduced leuco form followed by oxidation to the insoluble colourant. X/Y are listed as food colourants and Z as a textile colourant. These records are not formula-derived evidence of origin or regulatory approval.'),
    ('X ist nach Akte synthetisch; Lebensmittelverwendung beweist keine natürliche Herkunft. Y ist Polyen, nicht Azo, weil die N=N-Struktur fehlt. Z wird nach der beschriebenen Küpenmethode und nicht allein nach dem sichtbaren Endergebnis als Direktfarbstoff eingeordnet. X/Y haben dieselbe angegebene Verwendung, aber verschiedene Strukturklassen, Herkunft und Wasserlöslichkeit. „Farbig“ benennt weder Strukturklasse noch Herkunft, Mediums-Löslichkeit oder Färbeverfahren.', 'X is synthetic according to its record; food use does not prove natural origin. Y is polyene, not azo, because it lacks the N=N feature. Z is classified by the recorded vat process, not labelled a direct dye merely from the visible final result. X/Y share the recorded use but differ in structural class, origin and aqueous solubility. “Coloured” specifies neither structural class nor origin, medium-dependent solubility or colouring process.')], [['e1'], ['e2'], ['e3']]))

cases.append(case(1, '1', ('Unbenannte Strukturen mit dem Chromophor-Modell ordnen', 'Classify unnamed structures using the chromophore model'), (
    'Drei idealisierte, als Farbstoffe gegebene Strukturkarten ohne Familiennamen. Me ist Methyl, Ph Phenyl. U hat die Resonanzbeschreibung Me₂N–CH=CH–CH=N⁺Me₂ ↔ Me₂N⁺=CH–CH=CH–NMe₂: eine durchgehend konjugierte Methinkette verbindet die N-Endgruppen; die Gesamtladung ist +1. V ist [(p-Me₂N–C₆H₄)₂C(Ph)]⁺: drei Arylreste am zentralen, trigonal-planaren C; kein zentrales C–H, Gesamtladung +1. W hat ein Anthrachinon-Gerüst: zwei C=O-Gruppen im mittleren sechsgliedrigen Chinonring, der an beiden Seiten an Benzolringe anelliert ist; die Carbonylgruppen sind Teil des konjugierten Gerüsts. Gegenionen von U/V werden nicht gezeigt. Als Modellhilfe ist gegeben: Ein Chromophor bezeichnet den strukturellen Bereich, dem eine elektronische Absorptionsbande zugeordnet wird; bei einem sichtbaren Farbstoff ist die relevante Konjugation im Molekül zu prüfen. Keine Messwerte und keine Syntheserouten sind gegeben.',
    'Three idealized structure cards supplied as dyes, without family names. Me is methyl, Ph phenyl. U has the resonance description Me₂N–CH=CH–CH=N⁺Me₂ ↔ Me₂N⁺=CH–CH=CH–NMe₂: a continuously conjugated methine chain links the N end groups; net charge +1. V is [(p-Me₂N–C₆H₄)₂C(Ph)]⁺: three aryl residues on central trigonal-planar C; no central C–H, net charge +1. W has an anthraquinone framework: two C=O groups in the central six-membered quinone ring fused on both sides to benzene rings; carbonyl groups form part of the conjugated framework. Counterions of U/V are not shown. Model support: A chromophore denotes the structural region associated with an electronic absorption band; for a visible dye the relevant molecular conjugation must be examined. No measurements or synthesis routes are supplied.'), [
    ('Wende das Chromophor-Modell auf U/V/W an: beschreibe jeweils den konjugierten strukturellen Bereich und erläutere, warum nicht bloß ein isoliertes Einzelzeichen als Begründung genügt.', 'Apply the chromophore model to U/V/W: describe the conjugated structural region in each and explain why an isolated symbol alone is not sufficient justification.'),
    ('Ordne U/V/W den beispielhaften Klassen Polymethin-, Triphenylmethan- und Carbonylfarbstoffe zu und begründe jede Zuordnung durch das charakteristische Strukturelement.', 'Assign U/V/W to the illustrative polymethine, triphenylmethane and carbonyl dye classes and justify each assignment by its characteristic structural feature.'),
    ('Prüfe die Behauptungen „Jede N-haltige Struktur ist Polymethin“ und „Drei Arylreste machen das zentrale C zu einem Carbonyl-Chromophor“. Korrigiere beide mit Bezug auf die Karten.', 'Evaluate the claims “Every N-containing structure is polymethine” and “Three aryl residues make central C a carbonyl chromophore”. Correct both using the cards.')], [
    ('U: die konjugierte Methinkette und die beteiligten N-Endgruppen bilden den durch Resonanz beschriebenen Bereich. V: das sp²-artige kationische Zentralzentrum ist mit den Aryl-π-Systemen gekoppelt; die Aminodonoren können zur Delokalisierung beitragen. W: die C=O-Gruppen wirken innerhalb des anellierten konjugierten Chinon-Gerüsts. Das Modell ordnet den elektronischen Übergang einem strukturellen Bereich zu; N, ein Pluszeichen oder C=O allein beschreibt dessen Einbettung und Ausdehnung nicht.', 'U: the conjugated methine chain and participating N end groups form the region described by resonance. V: the sp²-like cationic central centre couples with aryl pi systems; amino donors can contribute to delocalization. W: C=O groups operate within the fused conjugated quinone framework. The model associates an electronic transition with a structural region; N, a plus sign or C=O alone does not describe its embedding and extent.'),
    ('U ist Polymethin: das kennzeichnende konjugierte Methinketten-System liegt vor. V ist Triphenylmethanfarbstoff: das zentrale kationische C ist an drei Arylreste gebunden und kann mit ihnen konjugieren. W ist Carbonylfarbstoff: die Carbonylgruppen gehören zum konjugierten Chinon-Chromophor. Die Zuordnung folgt aus dem Bau, nicht aus einem gegebenen Farbnamen oder einer Syntheseroute.', 'U is polymethine: it has the characteristic conjugated methine-chain system. V is a triphenylmethane dye: central cationic C is attached to three aryl residues and can conjugate with them. W is a carbonyl dye: its carbonyl groups belong to the conjugated quinone chromophore. Assignment follows from constitution, not a supplied colour name or synthesis route.'),
    ('N allein beweist keine Polymethinkette; V enthält N-Donoren, hat aber das Triphenylmethan-Gerüst. Drei Arylreste sind keine C=O-Gruppe: V hat ein kationisches Zentral-C ohne gebundenes O und darf deshalb nicht als Carbonylfarbstoff begründet werden. Für Carbonyl-Zuordnung muss ein tatsächliches, entsprechend eingebettetes C=O-Strukturelement vorliegen, wie in W.', 'N alone does not prove a polymethine chain; V contains N donors but has the triphenylmethane framework. Three aryl residues are not a C=O group: V has a cationic central C with no attached O, so this cannot justify a carbonyl-dye assignment. Carbonyl assignment requires an actual appropriately embedded C=O feature, as in W.')], [['e1'], ['e2'], ['e3']]))

cases.append(case(1, '2', ('Struktur statt Etikett: Farbstoffe und Nichtbeispiel', 'Structure rather than label: dyes and a non-example'), (
    'Neue schematische Papierkarten; Et bedeutet Ethyl, Ar_D den para-Ethoxyphenylrest p-EtO–C₆H₄. J: Et₂N–CH=CH–CH=CH–CH=N⁺Et₂ mit entsprechend delokalisierter positiver Ladung und durchgehend konjugierter Methinkette; laut Karte ein Farbstoff. K: [C(Ar_D)₃]⁺ mit trigonal-planarem Zentral-C ohne C–H-Bindung und drei donor-substituierten Arylresten; laut Karte ein Farbstoff. L: substituiertes 1,4-Benzochinon, O=C₁–C=C–C(=O)–C=C₁, mit donor-substituierten Ringpositionen; die C=O-Gruppen sind in das konjugierte Ringsystem eingebettet; laut Karte ein Carbonylfarbstoff. M: Aceton, CH₃–C(=O)–CH₃, laut Karte in der gegebenen Probe ohne sichtbare Farbstoffwirkung; seine isolierte Carbonylgruppe besitzt einen elektronischen Übergang im UV-Bereich. Die Etiketten J „synthetisch“, K „naturidentisch“, L „gelb“ sind zusätzliche Angaben ohne Strukturklassen-Beweis. Aufgabenmodell: Chromophor ist ein struktureller Bereich für eine Absorptionsbande, nicht automatisch ein Nachweis sichtbarer Farbe. Zahlenwerte, Reaktionswege und tatsächliche Experimente werden nicht benötigt.',
    'New schematic paper cards; Et means ethyl, Ar_D is the para-ethoxyphenyl residue p-EtO–C₆H₄. J: Et₂N–CH=CH–CH=CH–CH=N⁺Et₂ with a correspondingly delocalized positive charge and continuous conjugated methine chain; supplied as a dye. K: [C(Ar_D)₃]⁺ with central trigonal-planar C, no central C–H bond and three donor-substituted aryl residues; supplied as a dye. L: substituted 1,4-benzoquinone, O=C₁–C=C–C(=O)–C=C₁, with donor-substituted ring positions; C=O groups are embedded in the conjugated ring system; supplied as a carbonyl dye. M: acetone, CH₃–C(=O)–CH₃, supplied as having no visible dye effect in the specified sample; its isolated carbonyl group has an electronic transition in the UV region. The labels J “synthetic”, K “nature-identical”, L “yellow” are extra information without proof of structural class. Task model: a chromophore is a structural region for an absorption band, not automatically proof of visible colour. Numerical values, reaction routes and actual experiments are unnecessary.'), [
    ('Ordne J/K/L strukturell ein und begründe die Polymethin-, Triphenylmethan- bzw. Carbonylklasse durch Anwendung des Chromophor-Modells auf den jeweils zusammenhängenden Bereich. Nenne, welche Merkmale variieren können, ohne das jeweilige Klassenmerkmal zu verlieren; keine andere Fallalternative muss bearbeitet werden.', 'Classify J/K/L structurally and justify the polymethine, triphenylmethane and carbonyl classes by applying the chromophore model to the relevant continuous region. State which features can vary without losing each characteristic class feature; no other case needs to be completed.'),
    ('Erkläre, warum M zwar eine Carbonylgruppe als Chromophor für eine UV-Bande besitzt, anhand der Angaben aber kein Beispiel für einen sichtbaren Carbonylfarbstoff ist. Vergleiche dazu die Einbettung von C=O in M und L, ohne eine Wellenlänge vorherzusagen.', 'Explain why M has a carbonyl group as a chromophore for a UV band but, using the supplied information, is not an example of a visible carbonyl dye. Compare the embedding of C=O in M and L without predicting a wavelength.'),
    ('Prüfe, ob eine Vertauschung der Etiketten „synthetisch“, „naturidentisch“ und „gelb“ die Strukturzuordnung J/K/L verändern dürfte. Begründe die Entscheidung und benenne die für diese Zuordnung nötigen Belege.', 'Determine whether swapping the labels “synthetic”, “nature-identical” and “yellow” could change structural assignment of J/K/L. Justify the decision and identify the evidence needed for this classification.')], [
    ('J: Polymethin, weil die konjugierte Methinkette mit den beteiligten N-Endgruppen vorliegt; Kettenlänge und N-Substituenten können variieren. K: Triphenylmethan, weil ein kationisches, konjugationsfähiges Zentral-C an drei Arylreste gekoppelt ist; Aryl-Donorsubstituenten können variieren. L: Carbonylfarbstoff, weil die C=O-Gruppen Teil des konjugierten Chinonbereichs sind; Substituenten und die Einbettung in geeignete größere konjugierte Gerüste können variieren. Das jeweilige kennzeichnende konjugierte Bauprinzip muss erhalten bleiben.', 'J: polymethine, because it contains the conjugated methine chain with participating N end groups; chain length and N substituents can vary. K: triphenylmethane, because cationic central C capable of conjugation couples with three aryl residues; aryl donor substituents can vary. L: carbonyl dye, because C=O groups form part of the conjugated quinone region; substituents and embedding in suitable larger conjugated frameworks can vary. Each characteristic conjugated structural principle must remain.'),
    ('Ein Chromophor bezieht sich auf eine elektronische Bande; diese muss nicht im sichtbaren Bereich liegen. M hat eine isolierte C=O-Gruppe zwischen gesättigten Methylgruppen und laut Angabe nur die hier relevante UV-Bande, keine sichtbare Farbstoffwirkung. L hat die Carbonylgruppen im zusammenhängenden konjugierten Chinon-Gerüst und ist ausdrücklich als sichtbarer Farbstoff gegeben. Daher genügt „enthält C=O“ nicht, um jede Carbonylverbindung als Carbonylfarbstoff einzuteilen; keine genaue Spektralvorhersage folgt aus dieser Aufgabe.', 'A chromophore relates to an electronic band, which need not lie in the visible region. M has an isolated C=O group between saturated methyl groups and is supplied with the relevant UV band and no visible dye effect. L embeds its carbonyl groups in a continuous conjugated quinone framework and is explicitly supplied as a visible dye. Thus “contains C=O” is insufficient to classify every carbonyl compound as a carbonyl dye; no exact spectral prediction follows from this task.'),
    ('Nein. Herkunftsetiketten und ein Farbetikett ändern den vorgegebenen Bau nicht. Die Strukturzuordnung benötigt das Methinketten-System von J, das dreiaryl-substituierte kationische Zentralzentrum von K und die konjugiert eingebetteten C=O-Gruppen von L. Ein Farbname oder eine Herkunft allein ersetzt keine dieser Modellbegründungen.', 'No. Origin labels and a colour label do not change the supplied constitution. Structural assignment requires the methine-chain system of J, the triaryl-substituted cationic central centre of K and the conjugatively embedded C=O groups of L. Colour name or origin alone replaces none of these model-based justifications.')], [['e1', 'e2'], ['e1', 'e3'], ['e2', 'e3']]))

expectations = [
    [('e1', 'Strukturklassen werden mit charakteristischen Merkmalen vorgestellt und auf Azo sowie mindestens zwei weitere ausgewählte Klassen angewandt.', 'Structural classes are introduced using characteristic features and applied to azo and at least two further selected classes.', 'Ordnet vorgegebene Vertreter richtig ein und nennt für jede Zuordnung das relevante Strukturmerkmal.', 'Assigns supplied representatives correctly and gives the relevant structural feature for each assignment.'),
     ('e2', 'Molekülstruktur, Löslichkeit, Herkunft, Färbemethode und Verwendung sind verschiedene ausdrücklich zu benennende Einteilungskriterien.', 'Molecular constitution, solubility, origin, colouring method and use are distinct criteria that must be named explicitly.', 'Führt alle fünf Kriterien nachvollziehbar auf gegebene Materialakten zurück; bei Löslichkeit nennt sie/er das Medium und erfindet keine Herkunft oder Anwendung aus der Formel.', 'Traces all five criteria transparently to supplied records; specifies the medium for solubility and does not invent origin or use from the formula.'),
     ('e3', 'Eine Klassenzugehörigkeit entlang einer Achse bestimmt nicht automatisch die Einteilung entlang einer anderen.', 'Membership along one classification axis does not automatically determine classification along another.', 'Begründet an vertauschten oder kontrastierenden Beispielen gemeinsame und unterschiedliche Zuordnungen und korrigiert eine Vermischung der Kriterien.', 'Uses swapped or contrasting examples to justify shared and different assignments and corrects conflation of criteria.')],
    [('e1', 'Das Chromophor-Modell ordnet eine elektronische Bande einem relevanten strukturellen Bereich zu; charakteristische Gruppen sind in ihre Konjugation einzuordnen.', 'The chromophore model associates an electronic band with a relevant structural region; characteristic groups must be situated in their conjugation.', 'Beschreibt den konjugierten Bereich vorgegebener Farbstoffstrukturen, statt nur einen Namen oder eine einzelne Gruppe zu nennen.', 'Describes the conjugated region of supplied dye structures instead of merely giving a name or isolated group.'),
     ('e2', 'Die beispielhaften Klassen Polymethin, Triphenylmethan und Carbonyl werden über ihren Bau, nicht über Herkunft, Farbe oder Synthesekenntnis zugeordnet.', 'The illustrative polymethine, triphenylmethane and carbonyl classes are assigned through constitution, not origin, colour or synthesis knowledge.', 'Ordnet variierte Strukturkarten ein und begründet Methinkette, kationisches dreiaryl-substituiertes Zentrum bzw. konjugiert eingebettete Carbonylgruppen.', 'Classifies varied structure cards and justifies a methine chain, cationic triaryl-substituted centre or conjugatively embedded carbonyl groups.'),
     ('e3', 'Ein einzelnes N, Pluszeichen oder C=O ist kein hinreichender Beleg für die jeweilige Farbstoffklasse; Chromophore können auch außerhalb des sichtbaren Bereichs absorbieren.', 'An isolated N, plus sign or C=O is insufficient evidence for the respective dye class; chromophores can also absorb outside the visible region.', 'Korrigiert fehlerhafte Strukturzuordnungen und grenzt ein gegebenes Nichtbeispiel nachvollziehbar ab, ohne eine quantitative Spektralvorhersage zu verlangen.', 'Corrects faulty structural assignments and distinguishes a supplied non-example with justification, without requiring a quantitative spectral prediction.')]
]
